import{_ as a,a as t,c as i,ac as r}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"英语主动与被动语态","description":"主动与被动语态及进行时的区别","frontmatter":{"title":"英语主动与被动语态","description":"主动与被动语态及进行时的区别","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/English/2023-05-17-7-voice.md","date":"Sat May 16 2020 12:13:01 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"英语基础","summary":"主动与被动语态及进行时的区别","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"English 时态","link":"/life/english/foundations/6-tense"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"English 时态","link":"/life/english/foundations/6-tense"},"next":false},"headers":[],"relativePath":"life/english/foundations/7-voice.md","filePath":"life/english/foundations/7-voice.md"}'),n={name:"life/english/foundations/7-voice.md"};function l(s,e,o,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="英语主动与被动语态" tabindex="-1">英语主动与被动语态 <a class="header-anchor" href="#英语主动与被动语态" aria-label="Permalink to &quot;英语主动与被动语态&quot;">​</a></h1><p><span id="english-语态"></span></p><h2 id="语态" tabindex="-1">语态 <a class="header-anchor" href="#语态" aria-label="Permalink to &quot;语态&quot;">​</a></h2><h3 id="语态分类" tabindex="-1">语态分类 <a class="header-anchor" href="#语态分类" aria-label="Permalink to &quot;语态分类&quot;">​</a></h3><ul><li><strong>主动语态</strong>：主语是动作的执行者。例：The chef prepared the meal for the guests.（厨师为客人准备了餐点。）</li><li><strong>被动语态</strong>：主语是动作的承受者，常用 be + 过去分词。例：The meal was prepared by the chef for the guests.（餐点由厨师为客人准备。）</li></ul><h3 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表达</th><th>关注点</th></tr></thead><tbody><tr><td>The dog chased the cat.</td><td>执行追逐动作的狗</td></tr><tr><td>The cat was chased by the dog.</td><td>承受追逐动作的猫</td></tr></tbody></table><h2 id="与进行时的区别" tabindex="-1">与进行时的区别 <a class="header-anchor" href="#与进行时的区别" aria-label="Permalink to &quot;与进行时的区别&quot;">​</a></h2><p>The chef was preparing the meal when the guests arrived.（客人到达时，厨师正在准备餐点。）</p><p>这个句子使用过去进行时，语态仍是主动。进行时描述动作的时间和持续状态，不是与主动、被动并列的第三种语态。更多例句见 <a href="/life/english/foundations/6-tense">英语时态</a>。</p>',10)])])}const f=a(n,[["render",l]]);export{p as __pageData,f as default};
